        dy = 0
        if target_x > from_x:
            dx = 1
        elif target_x < from_x:
            dx = -1
        if target_y > from_y:
            dy = 1
        elif target_y < from_y:
            dy = -1
        return dx, dy

    # Helper to get distance
    def dist(a_x, a_y, b_x, b_y):
        return abs(a_x - b_x) + abs(a_y - b_y)

    # Priority 1: resources
    for r in resources:
        if r is None:
            continue
        rx, ry = r
        d = dist(x, y, rx, ry)
        if d == 1:
            return [rx - x, ry - y]
        elif d > 1:
            dx, dy = direction_towards(rx, ry, x, y)
            return [dx, dy]

    # Priority 2: enemies
    for enemy in enemies:
        if enemy is None:
            continue
        ex, ey = enemy.get('pos', [0, 0])
        d = dist(x, y, ex, ey)
        if d == 1:
            return [ex - x, ey - y]
        elif d > 1:
            dx, dy = direction_towards(ex, ey, x, y)
            return [dx, dy]

    # Priority 3: territory
    for idx, owner in enumerate(territory_control):
        if owner is None:
            continue
        if owner != 'own':
            tx = idx % width
            ty = idx // width
            d = dist(x, y, tx, ty)
